corrected_code:
@router.get("/analytics/api-usage-metrics")
async def get_customer_api_metrics(
    customer_code: str = Query(...),
    http_client: httpx.AsyncClient = Depends(get_http_client),
    current_user: User = Depends(get_current_user)
):
    if customer_code != current_user.customer_code and not current_user.is_analytics_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized customer metric query")

    prom_query = f'sum(rate(http_requests_total{{customer="{customer_code}", status=~"2.."}}[1h]))'
    resp = await http_client.get(
        "http://prometheus.internal:9090/api/v1/query",
        params={"query": prom_query}
    )
    return resp.json()
